def pair_with_sum(prices, target):
    left, right = 0, len(prices) - 1
    while left < right:
        total = prices[left] + prices[right]
        if total == target:
            return left, right
        if total < target:
            left += 1
        else:
            right -= 1
    return None


prices = [2, 5, 8, 12, 15, 21, 30]
for card in [20, 27, 4]:
    pair = pair_with_sum(prices, card)
    if pair is None:
        print(f"{card}: no pair")
    else:
        i, j = pair
        print(f"{card}: {prices[i]} + {prices[j]} at {i} and {j}")
